"""Questaal (all-electron FP-LMTO, lmf): init.<ext> written here, ctrl.<ext> generated by Questaal's own blm.

blm chooses the basis and sphere radii ("--express" = Questaal's standard defaults); we only pass
what the request asks for (functional switch, k-mesh). lmfa then makes free-atom densities and
estimates gmax, and lmchk checks sphere overlaps and symmetry. All three run in seconds.
"""

import os
import re
import shutil
import subprocess
from pathlib import Path

import numpy as np
from ase import Atoms
from ase.units import Bohr

from app.config import Settings
from app.dft.codes.base import CodeAdapter, ReadBack, Results
from app.dft.request import CalcRequest
from app.dft.structure import Cell, spacegroup_operations

# blm switches from `blm --h`; libxc ids it writes into xcfun, checked in libxc 6.2.2 xc_funcs.h
XC_SWITCH = {"PBE": "--pbe", "PBEsol": "--pbesol"}
LIBXC_IDS = {"PBE": (101, 130), "PBEsol": (116, 133)}
TIMEOUT_S = 180
EV_PER_RY = 13.605693122994


class QuestaalSetupError(RuntimeError):
    pass


def lib_path(lib_root: Path | None) -> str:
    """LD_LIBRARY_PATH entries for a Questaal built with Spack (libxc, hdf5, ...)."""
    base = os.environ.get("LD_LIBRARY_PATH", "")
    if not lib_root or not lib_root.is_dir():
        return base
    dirs = sorted({str(p) for pattern in ("*/*/lib", "*/*/lib64") for p in lib_root.glob(pattern) if p.is_dir()})
    return ":".join([*dirs, base]).strip(":")


def run(s: Settings, outdir: Path, args: list[str]) -> subprocess.CompletedProcess:
    exe = s.QUESTAAL_BIN / args[0]
    if not exe.is_file():
        raise QuestaalSetupError(f"{exe} not found")
    env = {**os.environ, "LD_LIBRARY_PATH": lib_path(s.QUESTAAL_LIB_ROOT), "OMP_NUM_THREADS": "1"}
    return subprocess.run([str(exe), *args[1:]], cwd=outdir, env=env, capture_output=True, text=True, timeout=TIMEOUT_S)


def init_text(cell: Cell, title: str) -> str:
    alat = float(np.linalg.norm(cell.lattice[0]))
    plat = cell.lattice / alat
    lines = [f"HEADER {title}", "LATTICE",
             "# ALAT in Å (UNITS=A); PLAT in units of ALAT; X = fractional coordinates",
             f"        ALAT={alat:.10f}  UNITS=A",
             "        PLAT=" + "  ".join(f"{x:15.10f}" for x in plat[0])]
    lines += ["             " + "  ".join(f"{x:15.10f}" for x in row) for row in plat[1:]]
    lines.append("SITE")
    lines += [f"     ATOM={el:<4} X= " + "  ".join(f"{x:13.10f}" for x in pos) for el, pos in zip(cell.symbols, cell.frac)]
    return "\n".join(lines) + "\n"


def set_gmax_from_lmfa(outdir: Path, ext: str, lmfa_out: str, basis_scale: float = 1.0) -> float:
    """blm --express leaves gmax=NULL; lmfa estimates it. Write that estimate into ctrl, as the tutorials do.
    basis_scale multiplies the energy cutoff, so gmax (a wavevector) scales with its square root."""
    m = re.search(r"estimate HAM_GMAX from RSMH:\s*GMAX=\s*([\d.]+)", lmfa_out)
    if not m:
        raise QuestaalSetupError("lmfa did not report a GMAX estimate; cannot complete ctrl")
    gmax = round(float(m.group(1)) * basis_scale ** 0.5, 3)
    ctrl = outdir / f"ctrl.{ext}"
    text, n = re.subn(r"(?m)^(\s*gmax=\s*)NULL\b", rf"\g<1>{gmax}", ctrl.read_text())
    if n != 1:
        raise QuestaalSetupError("expected exactly one 'gmax= NULL' in ctrl to fill in")
    ctrl.write_text(text)
    return gmax


def parse_lmchk(log: str) -> dict:
    vol = re.search(r"Cell vol(?:ume)?\s*=\s*([\d.]+)", log)
    nops = re.search(r"MKSYM:\s+found\s+(\d+)\s+space group operations", log)
    ovl = re.search(r"max ovlp\s*=\s*([-\d.]+)%", log)
    return {"cell_volume_bohr3": float(vol.group(1)) if vol else None,
            "space_group_operations": int(nops.group(1)) if nops else None,
            "max_sphere_overlap_percent": float(ovl.group(1)) if ovl else None}


def ext_of(outdir: Path) -> str:
    ctrl = next(outdir.glob("ctrl.*"), None)
    if ctrl is None:
        raise QuestaalSetupError(f"no ctrl file in {outdir}")
    return ctrl.suffix[1:]


class QuestaalAdapter(CodeAdapter):
    name, label, method, main_file = "questaal", "Questaal", "all-electron FP-LMTO (lmf)", "ctrl"
    program = "lmf"
    restartable = True  # lmf continues from rst.<ext> when rerun in the same folder

    def availability(self, s: Settings) -> tuple[bool, str]:
        if not s.QUESTAAL_BIN:
            return False, "QUESTAAL_BIN not set (folder with blm, lmfa, lmchk)"
        missing = [b for b in ("blm", "lmfa", "lmchk") if not (s.QUESTAAL_BIN / b).is_file()]
        if missing:
            return False, f"missing in {s.QUESTAAL_BIN}: {', '.join(missing)}"
        return True, f"binaries in {s.QUESTAAL_BIN}"

    def functionals(self) -> dict[str, str]:
        return XC_SWITCH

    def write(self, cell: Cell, req: CalcRequest, outdir: Path, s: Settings, title: str) -> dict:
        outdir.mkdir(parents=True, exist_ok=True)
        empirical = cell.atoms.get_chemical_formula(mode="metal", empirical=True).lower()
        ext = "".join(c for c in empirical if c.isalnum())[:12] or "crystal"  # Si2 -> si, Al4O6 -> al2o3
        (outdir / f"init.{ext}").write_text(init_text(cell, title))
        nk = ",".join(map(str, req.kmesh))
        blm_args = ["blm", "--express", XC_SWITCH[req.functional], f"--nk={nk}", "--ctrl=ctrl", "--digits", ext]
        radii = None
        if req.sphere_ref_scale and abs(req.sphere_ref_scale - req.volume_scale) > 1e-9:
            # Delta-test practice: radii that touch at the smallest volume, identical for every volume of an EOS
            from app.dft.structure import scaled

            ref = outdir / "_sphere_ref"
            ref.mkdir(exist_ok=True)
            (ref / f"init.{ext}").write_text(init_text(scaled(cell, req.sphere_ref_scale / req.volume_scale), title))
            if run(s, ref, blm_args).returncode != 0:
                raise QuestaalSetupError("blm failed on the sphere-reference cell")
            radii = dict(re.findall(r"atom=(\S+)\s+z=\s*\d+\s+r=\s*([\d.]+)", (ref / f"ctrl.{ext}").read_text()))
            shutil.rmtree(ref)
        steps, gmax = {}, None
        for name, args in (("blm", blm_args), ("lmfa", ["lmfa", ext]), ("lmchk", ["lmchk", ext])):
            p = run(s, outdir, args)
            (outdir / f"{name}.log").write_text(p.stdout + ("\n--- stderr ---\n" + p.stderr if p.stderr else ""))
            steps[name] = {"command": " ".join(args), "exit_code": p.returncode}
            if p.returncode != 0:
                raise QuestaalSetupError(f"{name} failed (exit {p.returncode}); see {name}.log:\n{(p.stderr or p.stdout)[-800:]}")
            if name == "blm" and radii:
                ctrl = outdir / f"ctrl.{ext}"
                text = ctrl.read_text()
                for atom, r in radii.items():
                    text = re.sub(rf"(atom={re.escape(atom)}\s+z=\s*\d+\s+r=\s*)[\d.]+", rf"\g<1>{r}", text)
                ctrl.write_text(text)
            if name == "lmfa":
                gmax = set_gmax_from_lmfa(outdir, ext, p.stdout, req.basis_scale)
        return {"files": sorted(f.name for f in outdir.iterdir() if f.is_file()),
                "set_explicitly": {"functional switch": XC_SWITCH[req.functional], "nk": nk,
                                   **({"sphere radii": f"touching at volume x{req.sphere_ref_scale}: {radii}"} if radii else {}),
                                   **({"gmax": f"x{req.basis_scale ** 0.5:.3f} the lmfa estimate"} if req.basis_scale != 1 else {})},
                "defaults": {"source": "blm --express (basis, sphere radii); lmfa (gmax)", "values": {"gmax": gmax}},
                "steps": steps}

    def read_back(self, outdir: Path, req: CalcRequest) -> ReadBack:
        ext = ext_of(outdir)
        site = (outdir / f"site.{ext}").read_text()
        header = next(ln for ln in site.splitlines() if ln.startswith("%"))
        alat = float(re.search(r"alat=\s*([-\d.Ee+]+)", header).group(1)) * Bohr
        plat = np.array([float(x) for x in re.search(r"plat=\s*([-\d.Ee+\s]+?)(?:\s+\w+=|$)", header).group(1).split()])
        rows = [ln.split() for ln in site.splitlines() if ln.strip() and not ln.startswith(("%", "#"))]
        pos = np.array([[float(x) for x in r[1:4]] for r in rows])
        lattice = plat.reshape(3, 3) * alat
        atoms = Atoms(symbols=[r[0] for r in rows], cell=lattice, pbc=True,
                      **({"scaled_positions": pos} if "xpos" in header else {"positions": pos * alat}))
        ctrl = (outdir / f"ctrl.{ext}").read_text()
        nk = re.search(r"(?im)^\s*nkabc=\s*([\d ]+)$", ctrl)
        xc = re.search(r"(?im)^\s*xcfun=\s*([\d,]+)", ctrl)
        xcfun = [int(x) for x in xc.group(1).split(",")] if xc else None
        gmax = re.search(r"(?im)^\s*gmax=\s*(\S+)", ctrl)
        lc = parse_lmchk((outdir / "lmchk.log").read_text())
        extra = [{"check": "gmax set (from lmfa)", "ok": bool(gmax and gmax.group(1) != "NULL"),
                  "detail": f"gmax={gmax.group(1) if gmax else None}"}]
        n = len(atoms)
        if lc["cell_volume_bohr3"]:
            extra.append({"check": "lmchk cell volume", "ok": abs(lc["cell_volume_bohr3"] * Bohr**3 / atoms.get_volume() - 1) < 1e-5,
                          "detail": f"lmchk {lc['cell_volume_bohr3']} bohr³ = {lc['cell_volume_bohr3'] * Bohr**3 / n:.6f} Å³/atom"})
        if lc["space_group_operations"] is not None:
            ops = spacegroup_operations(atoms)
            extra.append({"check": "lmchk symmetry operations", "ok": lc["space_group_operations"] == ops,
                          "detail": f"lmchk {lc['space_group_operations']}, spglib {ops}"})
        if lc["max_sphere_overlap_percent"] is not None:
            extra.append({"check": "muffin-tin spheres do not overlap", "ok": lc["max_sphere_overlap_percent"] <= 0,
                          "detail": f"max overlap {lc['max_sphere_overlap_percent']}%"})
        want = LIBXC_IDS.get(req.functional)
        return ReadBack(atoms=atoms, kmesh=[int(x) for x in nk.group(1).split()] if nk else None,
                        functional_ok=bool(want and xcfun and tuple(xcfun[1:3]) == want),
                        functional_detail=f"xcfun={xcfun}, expected libxc ids {want}", extra_checks=extra)

    def run_args(self, outdir: Path) -> dict:
        return {"program": self.program, "args": [ext_of(outdir)], "stdout": "lmf.out"}

    def local_env(self, s: Settings) -> dict[str, str]:
        return {"LD_LIBRARY_PATH": lib_path(s.QUESTAAL_LIB_ROOT)} if s.QUESTAAL_LIB_ROOT else {}

    def parse_results(self, rundir: Path) -> Results | None:
        """save.<ext>: one line per iteration; the last line starts with c (converged) or x (stopped unconverged).
        Gap and Fermi level from the last BZINTS block of lmf's output (Ry)."""
        try:
            ext = ext_of(rundir)
        except QuestaalSetupError:
            return None
        save = rundir / f"save.{ext}"
        if not save.is_file():
            return None
        lines = [ln for ln in save.read_text().splitlines() if ln.strip()]
        last = lines[-1] if lines else ""
        ehf = re.search(r"ehf=\s*([-\d.]+)", last)
        out = (rundir / "lmf.out").read_text(errors="replace") if (rundir / "lmf.out").is_file() else ""
        gap = re.findall(r"gap\s*=\s*[-\d.]+\s*Ry\s*=\s*([-\d.]+)\s*eV", out)
        ef = re.findall(r"BZINTS: Fermi energy:\s*([-\d.]+)", out)
        converged = last.startswith("c")
        return Results(converged=converged, total_energy_eV=float(ehf.group(1)) * EV_PER_RY if ehf else None,
                       fermi_eV=float(ef[-1]) * EV_PER_RY if ef else None, gap_eV=float(gap[-1]) if gap else None,
                       scf_iterations=sum(1 for ln in lines if ln[:1] in "ixc"),
                       warnings=[] if converged else ["last save line is not marked c (converged)"],
                       raw={"ehf_Ry": float(ehf.group(1)) if ehf else None, "save_last": last})
